def can_form_palindrome(s, k):
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1
    odd_count = sum(1 for c in count if c % 2 != 0)
    if odd_count > 1:
        return "NO"
    if k >= odd_count:
        return "YES"
    return "NO"


