def find_original_array(derived):
    n = len(derived)
    if n % 2 != 0:
        return False
    count = [0] * (n + 1)
    for d in derived:
        count[d] += 1
    for d in derived:
        if count[d] == 0:
            continue
        if d * 2 in count and count[d * 2] > 0:
            count[d] -= 1
            count[d * 2] -= 1
        else:
            return False
    return True

def longestEqualSubarray(nums, k):
    n = len(nums)
    count = [0] * (n + 1)
    max_len = 0
    for i in range(n):
        count[nums[i]] += 1
        if count[nums[i]] > 1:
            count[nums[i]] -= 1
        else:
            count[nums[i]] = 0
        if count[nums[i]] == 0:
            count[nums[i]] = 1
        max_len = max(max_len, i + 1 - count[nums[i]])
        if i - max_len + 1 > k:
            count[nums[i - max_len + 1]] += 1
    return max_len

