def maxScore(nums, x):
    n = len(nums)
    dp = [0] * n
    dp[0] = nums[0]
    for i in range(1, n):
        if nums[i] % 2 == nums[i - 1] % 2:
            dp[i] = max(dp[i - 1], dp[i - 1] + nums[i])
        else:
            dp[i] = dp[i - 1] + nums[i] - x
    return max(dp)

