def minSwaps(s: str) -> int:
    n = len(s)
    black_count = s.count('1')
    white_count = n - black_count
    return black_count - min(white_count, n - black_count)

def numGoodPartitions(nums):
    MOD = 10**9 + 7
    n = len(nums)
    partition = [0] * n
    for i in range(n):
        partition[i] = i
    for i in range(n-1, -1, -1):
        j = partition[i]
        while j < n and nums[j] == nums[i]:
            j += 1
        partition[i] = j
    return pow(2, partition.count(0), MOD)

