    for _ in range(K):
        x, y = map(int, input().split())
        xys.append((x, y))
    Q = int(input())
    pqs = []
    for _ in range(Q):
        p, q = map(int, input().split())
        pqs.append((p, q))

    # Check if the graph is good
    def is_good(graph):
        for x, y in xys:
            if x in graph and y in graph:
                if (x, y) in graph or (y, x) in graph:
                    return False
        return True

    # Add an edge and check if the graph is good
    def add_edge(graph, p, q):
        graph.add((p, q))
        if not is_good(graph):
            return False
        graph.remove((p, q))
        return True

    # Check each question
    for p, q in pqs:
        graph = set()
        for u, v in edges:
            graph.add((u, v))
        if add_edge(graph, p, q):
            print("Yes")
        else:
            print("No")

