def count_ways():
    N, T, M = map(int, input().split())
    incompatible_pairs = [list(map(int, input().split())) for _ in range(M)]
    ways = 0

    def is_valid(team):
        for a, b in incompatible_pairs:
            if a in team and b in team:
                return False
        return True

    def count_teams(team, remaining):
        nonlocal ways
        if len(remaining) == 0:
            if is_valid(team):
                ways += 1
            return
        for i in range(T):
            if i not in team:
                count_teams(team + [i], remaining - {i})

    count_teams(set(), set(range(T)))
    return ways

