def count_ice_squares():
    N, M = map(int, input().split())
    grid = [input() for _ in range(N)]
    player_position = (2, 2)
    visited = set()
    visited.add(player_position)
    count = 0
    for i in range(1, N-1):
        for j in range(1, M-1):
            if grid[i][j] == '.' and (i, j) not in visited:
                visited.add((i, j))
                count += 1
                while True:
                    if grid[i][j] == '#':
                        break
                    if i > 1 and grid[i-1][j] == '.':
                        i -= 1
                    elif i < N-2 and grid[i+1][j] == '.':
                        i += 1
                    elif j > 1 and grid[i][j-1] == '.':
                        j -= 1
                    elif j < M-2 and grid[i][j+1] == '.':
                        j += 1
                    else:
                        break
                visited.add((i, j))
                count += 1
    print(count)

