def strongest_programmer(N, M, info):
    # Create a list to store the superiority relations
    superiority = [[0]*N for _ in range(N)]

    # Populate the superiority list based on the input
    for a, b in info:
        superiority[a-1][b-1] = 1
        superiority[b-1][a-1] = 1

    # Create a list to store the strongest programmers
    strongest = []

    # Check each programmer to see if they are the strongest
    for i in range(N):
        is_strongest = True
        for j in range(N):
            if i != j and not superiority[i][j]:
                is_strongest = False
                break
        if is_strongest:
            strongest.append(i+1)

    # If there is only one strongest programmer, return their number
    if len(strongest) == 1:
        return strongest[0]

    # If there are multiple possible strongest programmers, return -1
    return -1

