def max_palindrome_length(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    max_len = 1
    for i in range(n):
        dp[i][i] = 1
        max_len = max(max_len, 1)
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j] and length == 2:
                dp[i][j] = 2
                max_len = max(max_len, 2)
            elif s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
                max_len = max(max_len, dp[i][j])
    return max_len

