def min_travel_time(N, A, B, C, D):
    # Initialize the distance matrix
    dist = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == j:
                dist[i][j] = 0
            else:
                dist[i][j] = D[i][j]

    # Floyd-Warshall algorithm to find the shortest paths
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Initialize the minimum time to travel from city 1 to city N
    min_time = float('inf')

    # Iterate over all possible intermediate cities
    for k in range(N):
        # Calculate the time to travel from city 1 to city N via city k
        time = dist[0][k] + dist[k][N-1]
        # Update the minimum time if the current time is smaller
        if time < min_time:
            min_time = time

    # Print the minimum time
    print(min_time)

