def game(N, cards):
    # Create a dictionary to store the count of each number
    count = {}
    for a, b in cards:
        if a in count:
            count[a] += 1
        else:
            count[a] = 1
        if b in count:
            count[b] += 1
        else:
            count[b] = 1

    # Sort the dictionary by the values in descending order
    sorted_count = sorted(count.items(), key=lambda x: x[1], reverse=True)

    # If the number of cards with the same front and back numbers is odd, Takahashi wins
    if len(sorted_count) % 2 == 1:
        return "Takahashi"
    else:
        return "Aoki"

