def shortestSubarray(nums, k):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] | nums[i]
    res = n + 1
    stack = [0]
    for i in range(1, n + 1):
        while stack and prefix[i] <= prefix[stack[-1]]:
            stack.pop()
        if stack and prefix[i] >= k:
            res = min(res, i - stack[-1])
        stack.append(i)
    return res if res <= n else -1

def sumOfPowers(nums, k):
    n = len(nums)
    MOD = 10**9 + 7
    dp = [[0]*k for _ in range(n+1)]
    dp[0][0] = 1
    for i in range(1, n+1):
        for j in range(k):
            if j < i:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1] * (nums[i-1] - nums[i-2]) % MOD) % MOD
    return sum(dp[n][j] for j in range(k)) % MOD

def is_valid_word(word):
    vowels = 'aeiouAEIOU'
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    if len(word) < 3:
        return False
    if not word.isalnum():
        return False
    if not any(char in vowels for char in word):
        return False
    if not any(char in consonants for char in word):
        return False
    return True

def maxEnergy(energy, k):
    n = len(energy)
    dp = [0] * n
    dp[0] = energy[0]
    for i in range(1, n):
        dp[i] = max(dp[i-1] + energy[i], energy[i])
    for i in range(k, n):
        dp[i] = max(dp[i-1] + energy[i], dp[i-k] + energy[i])
    return max(dp)

def is_special(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def powerfulArray(big_nums, queries):
    def generate_powerful_array(n):
        arr = [1]
        while sum(arr) < n:
            arr.append(arr[-1] * 2)
        return arr

    def product_modulo(arr, start, end, mod):
        prod = 1
        for i in range(start, end + 1):
            prod = (prod * arr[i]) % mod
        return prod

    big_nums = generate_powerful_array(10**15)
    result = []
    for query in queries:
        start, end, mod = query
        result.append(product_modulo(big_nums, start, end, mod))
    return result
